    atenciones.filter(Estado__iexact='Finalizada').update(Estado='FINALIZADA')
    atenciones.filter(Estado__iexact='Pagada').update(Estado='EN ESPERA')
    atenciones.filter(Estado__iexact='En espera').update(Estado='EN ESPERA')
    atenciones.filter(Estado__iexact='En atención').update(Estado='EN ATENCIÓN')
